// ===== ГЕНЕРАЦИЯ ТЕСТОВОГО НАБОРА =====
const baseUrl = 'http://localhost:5678/webhook-test/order-v2';

const tests = [
  // БЛОК A: Оригинал #1
  { label: 'ОРИГИНАЛ #1', customer: 'Алексей', contact: 'alexey@test.ru', text: 'Здравствуйте! Нужно масло OIL-5W40 2 шт', headers: {} },

  // БЛОК B: Лесенка E1-E6
  { label: 'E1 — без адреса', customer: 'Борис', contact: 'boris@test.ru', text: 'Нужно масло OIL-5W40 2 шт', headers: {} },
  { label: 'E2 — + адрес → DONE', customer: 'Борис', contact: 'boris@test.ru', text: 'Нужно масло OIL-5W40 2 шт. Доставка: г. Москва, ул. Тверская, д. 1, кв. 5', headers: {} },
  { label: 'E3 — срочно → DONE+surcharge', customer: 'Виктор', contact: 'viktor@test.ru', text: 'Срочно нужно масло OIL-5W40 2 шт! Доставка: г. Москва, ул. Тверская, д. 1, кв. 5. Примечание: позвоните перед доставкой', headers: {} },
  { label: 'E4 — мульти → DONE', customer: 'Галина', contact: 'galina@test.ru', text: 'Нужны колодки BRK-310 1 шт и фильтр воздушный FLT-200 3 шт. Доставка: г. Санкт-Петербург, Невский пр., д. 100', headers: {} },
  { label: 'E5 — вне каталога → NEEDS_REVIEW', customer: 'Дмитрий', contact: 'dmitry@test.ru', text: 'Нужен антифриз G12 5 литров. Доставка: г. Казань, ул. Баумана, д. 5', headers: {} },
  { label: 'E6 — смешанный → NEEDS_REVIEW', customer: 'Елена', contact: 'elena@test.ru', text: 'Нужно масло OIL-5W40 2 шт и антифриз G12 1 л. Доставка: г. Казань, ул. Баумана, д. 5', headers: {} },

  // БЛОК B: Особые случаи T2-T8
  { label: 'T2 — нет контакта → 422', customer: 'Тест', contact: '', text: 'Нужно масло', headers: {} },
  { label: 'T3 — длинный текст → 413', customer: 'Тест', contact: 'test_long@test.ru', text: 'А'.repeat(2500), headers: {} },
  { label: 'T4 — петля → 508', customer: 'Тест', contact: 'test_loop@test.ru', text: 'Тест петель', headers: { 'x-loop-depth': '1' } },
  { label: 'T5 — дубль E2 → DUPLICATE', customer: 'Борис', contact: 'boris@test.ru', text: 'Нужно масло OIL-5W40 2 шт. Доставка: г. Москва, ул. Тверская, д. 1, кв. 5', headers: {} },
  // T6 и T7 требуют ручной подготовки (сломать ключ / выключить settings) — помечены комментарием
  // { label: 'T6 — авария модели → 502', customer: 'Фёдор', contact: 'fedor@test.ru', text: 'Нужен фильтр масляный FLT-100 1 шт. Доставка: г. Новосибирск, ул. Ленина, д. 25', headers: {} },
  // { label: 'T7 — выключатель → 503', customer: 'Тест', contact: 'test_switch@test.ru', text: 'Тест выключателя', headers: {} },
  { label: 'T8a — лимит 1/2', customer: 'Спам', contact: 'spam@test.ru', text: 'Заказ номер 1', headers: {} },
  { label: 'T8b — лимит 2/2', customer: 'Спам', contact: 'spam@test.ru', text: 'Заказ номер 2', headers: {} },
  { label: 'T8c — лимит 3/2 → RATE_LIMITED', customer: 'Спам', contact: 'spam@test.ru', text: 'Заказ номер 3', headers: {} },

  // БЛОК C: Оригинал #2
  { label: 'ОРИГИНАЛ #2 — богатый', customer: 'Мария', contact: 'maria@test.ru', text: 'Здравствуйте! Нужны колодки тормозные BRK-310 2 шт и масло моторное OIL-5W40 1 шт. Доставка: г. Новосибирск, ул. Ленина, д. 25, кв. 8', headers: {} },

  // БЛОК D: Оригинал #3
  { label: 'ОРИГИНАЛ #3 — срочный самовывоз', customer: 'Пётр', contact: 'petr@test.ru', text: 'Срочно: нужен фильтр масляный FLT-100 1 шт. Самовывоз: г. Екатеринбург, ул. Ленина, д. 15, офис 3. Примечание: пропуск закажите заранее', headers: {} },
];

return tests.map(t => ({ json: { ...t, url: baseUrl } }));

// ===== СБОР РЕЗУЛЬТАТОВ =====
const results = $input.all().map(item => {
  const label = item.json.label || 'unknown';
  const statusCode = item.json.statusCode || item.json.error?.statusCode || 'N/A';
  const body = item.json.body || item.json.error?.message || '';
  return { label, statusCode, body: typeof body === 'string' ? body.slice(0, 200) : JSON.stringify(body).slice(0, 200) };
});

const summary = results.map(r => `${r.label} → ${r.statusCode}`).join('\n');
return [{ json: { summary, results } }];
